// The nine criteria from the EDPB/WP29 guidelines on DPIA (WP248 rev.01, section III.B). Two or more
// usually mean a DPIA is required. Edit keywords and titles in the dpia_criteria table after the first run.
const rows = [
  ['evaluation_or_scoring', 'Evaluation or scoring', 'Profiling or predicting aspects of a person: performance at work, health, preferences, interests, reliability, behaviour, location or movements.', 'profil|scor|predict|rating|credit|behaviour|behavior|preference', 'evaluation_or_scoring'],
  ['automated_decisions', 'Automated decisions with legal or similar effect', 'Decisions about a person taken by a system without meaningful human review, with legal or similarly significant effects.', 'automated decision|automatic decision|without human|auto-reject|auto reject|algorithm decides', 'automated_decisions'],
  ['systematic_monitoring', 'Systematic monitoring', 'Observing, monitoring or controlling people, including data collected through networks or in publicly accessible spaces.', 'monitor|surveillance|cctv|camera|tracking|track |geolocation|keylog|screen record', 'systematic_monitoring'],
  ['sensitive_data', 'Sensitive or highly personal data', 'Special categories (health, biometrics, genetics, sexual life, religion, politics, union, ethnicity), criminal data, or data of a highly personal nature such as finances or private communications.', 'health|medical|biometric|genetic|religio|ethnic|sexual|political|trade union|criminal|conviction|bank account|salary|private message', 'special_categories'],
  ['large_scale', 'Data processed on a large scale', 'Many data subjects, large volume or variety of data, long duration, or wide geographic reach.', 'nationwide|millions|large scale|all customers|all employees|entire population', 'estimated_subjects'],
  ['matching_or_combining', 'Matching or combining datasets', 'Combining data from different sources or purposes in a way the data subject would not reasonably expect.', 'combin|merge|match|cross-reference|cross reference|enrich|join with|third-party data|third party data', 'matching_datasets'],
  ['vulnerable_subjects', 'Data concerning vulnerable people', 'Children, employees, patients, elderly people, asylum seekers, or anyone in an imbalance of power with the controller.', 'child|minor|pupil|student|patient|employee|elderly|asylum|refugee|disab', 'vulnerable_subjects'],
  ['innovative_technology', 'Innovative use or new technology', 'New technology or a new way of using an existing one, such as AI, facial recognition, IoT, or fingerprinting, where the effects are not yet well understood.', 'artificial intelligence|machine learning|ai model|facial recognition|face recognition|iot|smart device|wearable|fingerprint|llm|language model', 'innovative_technology'],
  ['prevents_rights_or_service', 'Prevents exercising a right or using a service', 'Processing whose outcome can deny a person a service, a contract, a benefit or a right.', 'deny|denied|refuse|reject|exclude|blacklist|block access|screen out', 'prevents_rights_or_service']
];
return rows.map(r => ({ json: { criterion_key: r[0], title: r[1], description: r[2], keywords: r[3], form_field: r[4] } }));

const form = $('Describe The Processing').first().json;
const policy = $('Set Screening Policy').first().json;
const criteria = $input.all().map(i => i.json).filter(c => c && c.criterion_key);
const requiredAt = Number(policy.required_threshold) || 2;
const considerAt = Number(policy.consider_threshold) || 1;
const minChars = Number(policy.min_description_chars) || 40;
const text = [form.description, form.data_categories, form.data_subjects].map(v => String(v || '')).join(' \n ');
const lower = text.toLowerCase();
const yes = v => String(v || '').trim().toLowerCase() === 'yes';
const unsure = v => String(v || '').trim().toLowerCase() === 'not sure';
const bigScale = String(form.estimated_subjects || '');
const met = [];   // { criterion_key, title, source, evidence }
const unsureKeys = [];
for (const c of criteria) {
  const sources = [];
  const f = String(c.form_field || '');
  if (f === 'estimated_subjects') {
    if (/10,000 to 100,000|over 100,000/i.test(bigScale)) sources.push({ source: 'form', evidence: 'estimated_subjects = ' + bigScale });
  } else if (f && yes(form[f])) {
    sources.push({ source: 'form', evidence: f + ' = Yes' });
  } else if (f && unsure(form[f])) {
    unsureKeys.push(c.criterion_key);
  }
  const kws = String(c.keywords || '').split('|').map(s => s.trim().toLowerCase()).filter(Boolean);
  const hit = kws.find(k => lower.includes(k));
  if (hit) sources.push({ source: 'keyword', evidence: 'the description contains "' + hit + '"' });
  if (sources.length) met.push({ criterion_key: c.criterion_key, title: c.title, source: sources.map(s => s.source).join('+'), evidence: sources.map(s => s.evidence).join('; ') });
}
let verdict, verdictReason;
if (!criteria.length) { verdict = 'INCOMPLETE'; verdictReason = 'the dpia_criteria table is empty, so nothing could be screened; run Set Up Tables first'; }
else if (String(form.description || '').trim().length < minChars) { verdict = 'INCOMPLETE'; verdictReason = 'the description is shorter than ' + minChars + ' characters; too little to screen'; }
else if (met.length >= requiredAt) { verdict = 'REQUIRED'; verdictReason = met.length + ' criteria met; the EDPB guidelines say two or more usually mean a DPIA is required'; }
else if (met.length >= considerAt) { verdict = 'CONSIDER'; verdictReason = met.length + ' criterion met; one criterion can be enough, decide with your DPO'; }
else { verdict = 'NOT_REQUIRED'; verdictReason = 'no criterion met by the form answers or the description; keep this record as the reason'; }
const criteriaList = criteria.map(c => c.criterion_key + ': ' + c.title + ' (' + c.description + ')').join('\n');
const judgePrompt = 'CRITERIA:\n' + criteriaList + '\n\nALREADY MET (do not repeat): ' + (met.map(m => m.criterion_key).join(', ') || 'none') +
  '\n\nDESCRIPTION OF THE PROCESSING:\n' + text +
  '\n\nList any criterion that the description shows but which is not already met. For each, give the criterion_key and a verbatim quote (at least four words, copied exactly) from the DESCRIPTION that shows it. If nothing more is shown, return an empty list.';
return [{ json: {
  screening_id: $execution.id,
  screened_at: new Date().toISOString(),
  project_name: String(form.project_name || ''),
  owner_team: String(form.owner_team || ''),
  description: String(form.description || ''),
  text,
  criteria_loaded: criteria.length,
  criteria_keys: criteria.map(c => c.criterion_key),
  criteria_titles: Object.fromEntries(criteria.map(c => [c.criterion_key, c.title])),
  met, unsure_keys: unsureKeys,
  required_threshold: requiredAt, consider_threshold: considerAt,
  rule_verdict: verdict, rule_reason: verdictReason,
  judge_prompt: judgePrompt
} }];

const s = $('Score The Criteria').first().json;
const judgeItem = $input.first().json || {};
const out = judgeItem.output && typeof judgeItem.output === 'object' ? judgeItem.output : null;
let judgeStatus, judgeNote = '';
const added = [];
const rejected = [];
if (out && Array.isArray(out.additional_criteria)) {
  judgeStatus = 'answered';
  judgeNote = String(out.note || '');
  const lower = String(s.text || '').toLowerCase();
  for (const a of out.additional_criteria) {
    const key = String((a && a.criterion_key) || '').trim();
    const quote = String((a && a.quote) || '').trim();
    if (!s.criteria_keys.includes(key)) { rejected.push(key + ': unknown criterion'); continue; }
    if (s.met.some(m => m.criterion_key === key) || added.some(m => m.criterion_key === key)) { rejected.push(key + ': already met'); continue; }
    if (quote.length < 12 || !lower.includes(quote.toLowerCase())) { rejected.push(key + ': quote not found in the description'); continue; }
    added.push({ criterion_key: key, title: s.criteria_titles[key] || key, source: 'judge', evidence: 'quoted from the description: "' + quote.slice(0, 200) + '"' });
  }
} else {
  judgeStatus = 'did not answer';
  judgeNote = 'judge did not answer' + (judgeItem.error ? ': ' + String(judgeItem.error.message || judgeItem.error).slice(0, 160) : '');
}
const all = s.met.concat(added);
let verdict = s.rule_verdict, reason = s.rule_reason;
if (verdict !== 'INCOMPLETE') {
  if (all.length >= s.required_threshold) { verdict = 'REQUIRED'; reason = all.length + ' criteria met (' + s.met.length + ' by rules, ' + added.length + ' added by the judge with a quote); two or more usually mean a DPIA is required'; }
  else if (all.length >= s.consider_threshold) { verdict = 'CONSIDER'; reason = all.length + ' criterion met; one can be enough, decide with your DPO'; }
}
const lines = all.map(m => '- ' + m.title + ' [' + m.source + ']: ' + m.evidence);
if (s.unsure_keys.length) lines.push('- Answered "Not sure": ' + s.unsure_keys.join(', ') + ' (not counted; a person should decide)');
if (rejected.length) lines.push('- Judge suggestions not counted: ' + rejected.join('; '));
lines.push('- Judge: ' + judgeStatus + (judgeNote ? ' (' + judgeNote.slice(0, 200) + ')' : ''));
const report = 'Verdict ' + verdict + ': ' + reason + '\n' + lines.join('\n');
return [{ json: Object.assign({}, s, {
  criteria_all: all,
  criteria_count: all.length,
  criteria_met_text: all.map(m => m.criterion_key).join(', ') || 'none',
  judge_added_text: added.map(m => m.criterion_key).join(', ') || 'none',
  judge_status: judgeStatus, judge_note: judgeNote,
  verdict, verdict_reason: reason, report,
  description_excerpt: String(s.description || '').slice(0, 300)
}) }];

const d = $('Combine Into A Verdict').first().json;
const rows = d.criteria_all.map(m => ({ json: { screening_id: d.screening_id, project_name: d.project_name, criterion_key: m.criterion_key, source: m.source, evidence: String(m.evidence).slice(0, 400), found_at: d.screened_at } }));
if (!rows.length) rows.push({ json: { screening_id: d.screening_id, project_name: d.project_name, criterion_key: 'none', source: 'rules', evidence: 'no criterion met; verdict ' + d.verdict, found_at: d.screened_at } });
return rows;

