const policy = $('Set Digest Policy').first().json;
const days = Number(policy.lookback_days) || 7;
const cutoff = new Date(Date.now() - days * 86400 * 1000).toISOString();
const rows = $input.all().map(i => i.json).filter(r => r && r.screened_at && String(r.screened_at) >= cutoff);
const by = {}; for (const r of rows) { const v = r.verdict || 'UNKNOWN'; by[v] = (by[v] || 0) + 1; }
const required = rows.filter(r => r.verdict === 'REQUIRED').map(r => r.project_name + ' (' + String(r.criteria_met || '') + ')');
const incomplete = rows.filter(r => r.verdict === 'INCOMPLETE').length;
const quiet = rows.length === 0;
const needs = quiet ? Boolean(policy.post_when_quiet) : ((by.REQUIRED || 0) + (by.CONSIDER || 0) + incomplete) > 0;
const now = new Date().toISOString();
let summary;
if (quiet) summary = 'No screenings recorded in the last ' + days + ' days (since ' + cutoff.slice(0, 10) + '). Silence is not evidence that nothing was started; check that the form is in use.';
else summary = rows.length + ' screenings in the last ' + days + ' days: ' + (by.REQUIRED || 0) + ' DPIA required, ' + (by.CONSIDER || 0) + ' to consider, ' + (by.NOT_REQUIRED || 0) + ' not required, ' + incomplete + ' incomplete.' + (required.length ? ' DPIA required for: ' + required.join('; ') + '.' : '');
return [{ json: { digest_for: cutoff.slice(0, 10) + ' to ' + now.slice(0, 10), screenings: rows.length, required: by.REQUIRED || 0, consider: by.CONSIDER || 0, not_required: by.NOT_REQUIRED || 0, incomplete, needs_attention: needs, summary } }];
